/* ============================================================================
 * _build-bundle.mjs — extract lower-layer component CSS into a single bundle so
 * the consuming layer can compose by class without redefining anything.
 *
 * design-deconstruct staged tooling. Copied into <output>/_build-bundle.mjs.
 *
 *   node _build-bundle.mjs molecules   → molecules/_lower.css  (.atom-* rules)
 *   node _build-bundle.mjs organisms   → organisms/_lower.css  (.atom-* + .mol-*)
 *   node _build-bundle.mjs views       → views/_lower.css      (+ .org-*)
 *
 * Rules kept per source layer: selectors containing the layer prefix
 * (.atom-/.mol-/.org-) + every @keyframes (deduped by name) + @media blocks
 * that contain the prefix. Preview-chrome helpers (.mc-*, .sm-*, etc.) are dropped.
 *
 * Post theme-split, the canonical rule source is each component's dark.html
 * (its .atom/.mol/.org-* rules are identical to light.html — only the themed
 * token VALUES differ, and those live in tokens.css, not here).
 * ========================================================================== */
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
const DIR = dirname(fileURLToPath(import.meta.url));

// Each source layer keeps rules matching ITS prefix + every lower prefix, because
// a higher-layer component may legitimately add lower-namespace modifier classes
// (e.g. a molecule adding `.atom-label--side`). Keeps those in the bundle.
const SOURCES = {
  molecules: [['atoms', ['.atom-']]],
  organisms: [['atoms', ['.atom-']], ['molecules', ['.atom-', '.mol-']]],
  views:     [['atoms', ['.atom-']], ['molecules', ['.atom-', '.mol-']], ['organisms', ['.atom-', '.mol-', '.org-']]],
};
const target = process.argv[2];
if (!SOURCES[target]) { console.error('usage: node _build-bundle.mjs <molecules|organisms|views>'); process.exit(2); }

const stripComments = (s) => s.replace(/\/\*[\s\S]*?\*\//g, '');
function styleBlocks(html) { return [...html.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/g)].map(m => m[1]).join('\n'); }

function topLevelRules(css) {
  const rules = []; let i = 0; const n = css.length;
  while (i < n) {
    while (i < n && /\s/.test(css[i])) i++;
    if (i >= n) break;
    const start = i;
    while (i < n && css[i] !== '{') i++;
    if (i >= n) break;
    const prelude = css.slice(start, i).trim();
    let depth = 1; i++;
    while (i < n && depth > 0) { if (css[i] === '{') depth++; else if (css[i] === '}') depth--; i++; }
    rules.push({ prelude, full: css.slice(start, i).trim() });
  }
  return rules;
}

const out = [`/* GENERATED by _build-bundle.mjs — bundle for ${target} (do not edit) */`];
const seenKeyframes = new Set();
let kept = 0, kf = 0;

for (const [srcLayer, prefixes] of SOURCES[target]) {
  const layerDir = join(DIR, srcLayer);
  if (!existsSync(layerDir)) continue;
  const comps = readdirSync(layerDir, { withFileTypes: true })
    .filter(d => d.isDirectory() && !d.name.startsWith('_')).map(d => d.name).sort();
  out.push(`\n/* ─────────── ${srcLayer} (${prefixes.join(' ')}) ─────────── */`);
  for (const c of comps) {
    // canonical rule source is dark.html (identical .atom/.mol/.org-* rules to light.html)
    const html = existsSync(join(layerDir, c, 'dark.html')) ? join(layerDir, c, 'dark.html') : join(layerDir, c, `${c}.html`);
    if (!existsSync(html)) continue;
    const css = stripComments(styleBlocks(readFileSync(html, 'utf8')));
    const local = [];
    for (const r of topLevelRules(css)) {
      const kfm = r.prelude.match(/^@keyframes\s+([\w-]+)/);
      if (kfm) { if (!seenKeyframes.has(kfm[1])) { seenKeyframes.add(kfm[1]); local.push(r.full); kf++; } continue; }
      if (r.prelude.startsWith('@media')) { if (prefixes.some(p => r.full.includes(p))) { local.push(r.full); kept++; } continue; }
      if (prefixes.some(p => r.prelude.includes(p))) { local.push(r.full); kept++; }
    }
    if (local.length) { out.push(`/* ${c} */`); out.push(...local); }
  }
}

const dest = join(DIR, target, '_lower.css');
writeFileSync(dest, out.join('\n') + '\n');
console.log(`${target}/_lower.css written · ${kept} component rules · ${kf} keyframes · ${out.join('\n').length} bytes`);
